fix.code:
public enum Role { ADMIN, USER }

public class AccessChecker {
    public boolean isAdmin(String role) {
        return "ADMIN".equals(role);           // so sánh nội dung, an toàn khi role là null
    }

    // Tốt hơn: parse một lần ở biên hệ thống rồi dùng enum
    public boolean isAdmin(Role role) {
        return role == Role.ADMIN;             // enum là singleton nên == là đúng
    }
}
